 static Button ToolButton33(string icon,string hint){var button=new Button{Content=UiIcon32.Create(icon),ToolTip=hint,Padding=new(4),Margin=new(1,0,1,0),MinWidth=28,MinHeight=28};button.SetResourceReference(StyleProperty,"GhostIconButton");return button;}

 public static List<(string Title,string Body)> Sections(string text){var result=new List<(string,string)>();string title="Результат";var body=new StringBuilder();foreach(var line in text.Replace("\r\n","\n").Split('\n')){if(line.StartsWith("## ")){if(body.ToString().Trim().Length>0)result.Add((title,body.ToString().TrimEnd()));title=line[3..];body.Clear();}else body.AppendLine(line);}if(body.ToString().Trim().Length>0)result.Add((title,body.ToString().TrimEnd()));return result;}
 public string VisibleText()=>string.Join(Environment.NewLine+Environment.NewLine,groups.Children.OfType<Expander>().Where(e=>e.IsExpanded).Select(e=>((e.Header as TextBlock)?.Text??e.Header.ToString())+Environment.NewLine+(e.Tag as string??"")));
 public void ClearDisplay(){clearedText=Text;groups.Children.Clear();hits.Clear();currentHit=-1;counter.Text="";}
 public void SetExpanded(string title,bool open){expanded[title]=open;Render();}
 public static string LineTone(string line){if(line.StartsWith("Последний отчёт клиента: "))return ReportPresentation35.ReportLineTone(line);if(line.StartsWith("Последнее соединение с WSUS:"))return "Normal";if(Regex.IsMatch(line,@"К установке:\s*0\b")&&!line.Contains("неизвест")&&!line.Contains("больше"))return "Success";if(line.StartsWith("К установке:"))return line.Contains("— ·")||line.Contains("≥")?"Warning":"Info";if(line.StartsWith("Далее:")||line.StartsWith("Первое действие:"))return "Info";if(Regex.IsMatch(line,@"(?i)ResultCode\s+2\b.*HRESULT\s+0\s*\(0x00000000\)"))return "Success";if(Regex.IsMatch(line,@"(?i)данные расходятся|не окончательный|код.*не получен|0x80242014|ожидается установка|предыдущее событие|прежняя неудачная"))return "Warning";if(Regex.IsMatch(line,@"(?i)ошибок:\s*0\b|без замечаний|не обнаружила нарушений|отчётность работает"))return "Success";if(Regex.IsMatch(line,@"(?i)предупреж|неполн|частичн|не расшифр|не подтвержд|ограничени|рекомендаци|рекоменду|Предыдущий снимок|WARNING|retry"))return "Warning";if(LogPresentation.Anomaly(line))return "Error";if(Regex.IsMatch(line,@"(?i)успешно|получен сервером|Succeeded|Очистка очереди.*не требуется"))return "Success";return "Normal";}
 void ScheduleRender(){if(renderPending)return;renderPending=true;Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Background,new Action(()=>{renderPending=false;Render();}));}
 public static List<(int Start,int Length)> MatchRanges(string text,string query){var result=new List<(int,int)>();if(string.IsNullOrEmpty(query))return result;int start=0,index;while(start<text.Length&&(index=text.IndexOf(query,start,StringComparison.OrdinalIgnoreCase))>=0){result.Add((index,query.Length));start=index+query.Length;}return result;}
 void MoveMatch(int delta){if(hits.Count==0)return;if(currentHit>=0)hits[currentHit].Run.Background=Brushes.DarkSlateBlue;currentHit=currentHit<0?(delta<0?hits.Count-1:0):(currentHit+delta+hits.Count)%hits.Count;var hit=hits[currentHit];hit.Run.Background=Brushes.DarkGoldenrod;hit.Group.IsExpanded=true;hit.Box.UpdateLayout();hit.Box.Selection.Select(hit.Run.ContentStart,hit.Run.ContentEnd);hit.Box.BringIntoView(hit.Run.ContentStart.GetCharacterRect(LogicalDirection.Forward));counter.Text=(currentHit+1)+" / "+hits.Count;}
 void Render(){if(clearedText==Text)return;clearedText=null;double offset=scroll.VerticalOffset;groups.Children.Clear();hits.Clear();currentHit=-1;int remainingLines=1800;foreach(var (title,body) in Sections(Text??"")){string display=body;if(filter.SelectedIndex==1)display=LogPresentation.ErrorContext(body);if(filter.SelectedIndex==2)display=string.Join("\n",body.Split('\n').Where(x=>LineTone(x)=="Warning"));if(filter.SelectedIndex>0&&(display.Length==0||display.StartsWith("В выбранном интервале")))continue;display=System.Text.RegularExpressions.Regex.Replace(display.Replace("\r\n","\n"),@"\n(?:[ \t]*\n)+","\n");var lines=display.Split('\n');if(lines.Length>remainingLines)display=string.Join("\n",lines.Take(Math.Max(0,remainingLines)))+"\n… Краткий вывод ограничен. Полные исходные файлы — кнопка «Журналы».";remainingLines-=Math.Min(lines.Length,remainingLines);if(remainingLines==0&&groups.Children.Count>0&&display.StartsWith("\n…"))continue;var expander=new Expander{Header=new TextBlock{Text=title,Foreground=Theme.Brush("TextPrimary"),FontWeight=FontWeights.SemiBold,FontFamily=new FontFamily("Segoe UI"),Padding=new(6,0,6,0)},Background=Theme.Brush("SectionSurface"),Foreground=Theme.Brush("TextPrimary"),Margin=new(0,0,0,1),IsExpanded=expanded.TryGetValue(title,out bool open)?open:!title.StartsWith("Техничес")&&!title.StartsWith("Сбор диагностики")};var document=new FlowDocument{PagePadding=new(0)};var paragraph=new Paragraph{Margin=new(0),LineHeight=16,LineStackingStrategy=LineStackingStrategy.BlockLineHeight};var box=new RichTextBox{Document=document,IsReadOnly=true,IsDocumentEnabled=false,FontFamily=new FontFamily("Consolas"),Background=BodyBrush,BorderThickness=new(0),Padding=new(6,3,6,3),VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};var codeMatch=Regex.Match(display,@"(?i)0x[89a-f][0-9a-f]{7}");if(codeMatch.Success){var menu=new ContextMenu();var find=new MenuItem{Header="Найти описание "+codeMatch.Value+" в Microsoft Learn"};find.Click+=(s,e)=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://www.bing.com/search?q="+Uri.EscapeDataString(codeMatch.Value+" site:learn.microsoft.com")){UseShellExecute=true});menu.Items.Add(find);box.ContextMenu=menu;}bool firstLine=true;foreach(var line in display.Split('\n')){if(!firstLine)paragraph.Inlines.Add(new LineBreak());firstLine=false;string tone=LineTone(line);if(tone=="Normal"&&(title.Contains("Рекомендац",StringComparison.OrdinalIgnoreCase)||title.Contains("Автоматическая диагностика",StringComparison.OrdinalIgnoreCase)))tone="Warning";Brush color=Theme.Tone(tone);var weight=ReportPresentation35.Emphasized(line)?FontWeights.Bold:tone is "Error" or "Warning"?FontWeights.SemiBold:FontWeights.Normal;int pos=0;foreach(var match in MatchRanges(line,search.Text)){if(match.Start>pos)paragraph.Inlines.Add(new Run(line[pos..match.Start]){Foreground=color,FontWeight=weight});var run=new Run(line.Substring(match.Start,match.Length)){Foreground=Brushes.White,Background=Brushes.DarkSlateBlue,FontWeight=FontWeights.Bold};paragraph.Inlines.Add(run);hits.Add((run,box,expander));pos=match.Start+match.Length;}if(pos<line.Length)paragraph.Inlines.Add(new Run(line[pos..]){Foreground=color,FontWeight=weight});}document.Blocks.Add(paragraph);expander.Tag=display;expander.Content=box;expander.Expanded+=(s,e)=>expanded[title]=true;expander.Collapsed+=(s,e)=>expanded[title]=false;groups.Children.Add(expander);}counter.Text=search.Text.Length==0?"":"0 / "+hits.Count;scroll.ScrollToVerticalOffset(offset);if(AutoScroll&&search.Text.Length==0)scroll.ScrollToEnd();}
